mapper.sql:
SELECT 'FOLLOWUP' AS fact_type, f.id AS source_id, f.id AS parent_id, NULL AS order_id, f.customer_id, NULL AS campaign_id, NULL AS campaign_batch_id, NULL AS sku_id, f.contact_at AS event_at, NULL AS amount_fen, NULL AS quantity, NULL AS source_system, NULL AS receiver_type FROM crm_followup f INNER JOIN crm_customer c ON c.tenant_id = f.tenant_id AND c.id = f.customer_id AND c.deleted = 0 WHERE f.tenant_id = #{query.tenantId} AND f.deleted = 0 AND f.contact_at IS NOT NULL AND f.contact_at >= #{query.window.fromUtc} AND f.contact_at < #{query.window.toUtcExclusive}
AND f.customer_id = #{query.criteria.customerId} UNION ALL SELECT 'APPOINTMENT_CONFIRMED', h.id, a.id, NULL, a.customer_id, NULL, NULL, NULL, h.created_at, NULL, NULL, NULL, NULL FROM crm_appointment_history h INNER JOIN crm_appointment a ON a.tenant_id = h.tenant_id AND a.id = h.appointment_id INNER JOIN crm_customer c ON c.tenant_id = a.tenant_id AND c.id = a.customer_id AND c.deleted = 0 WHERE h.tenant_id = #{query.tenantId} AND h.to_status = 'CONFIRMED' AND h.created_at >= #{query.window.fromUtc} AND h.created_at < #{query.window.toUtcExclusive}
AND a.customer_id = #{query.criteria.customerId} AND a.institution_id = #{query.criteria.institutionId} UNION ALL SELECT 'CHECKED_IN', h.id, a.id, NULL, a.customer_id, NULL, NULL, NULL, h.created_at, NULL, NULL, NULL, NULL FROM crm_appointment_history h INNER JOIN crm_appointment a ON a.tenant_id = h.tenant_id AND a.id = h.appointment_id INNER JOIN crm_customer c ON c.tenant_id = a.tenant_id AND c.id = a.customer_id AND c.deleted = 0 WHERE h.tenant_id = #{query.tenantId} AND h.to_status = 'CHECKED_IN' AND h.created_at >= #{query.window.fromUtc} AND h.created_at < #{query.window.toUtcExclusive}
AND a.customer_id = #{query.criteria.customerId} AND a.institution_id = #{query.criteria.institutionId} UNION ALL SELECT 'SERVICE_DONE', h.id, a.id, NULL, a.customer_id, NULL, NULL, NULL, h.created_at, NULL, NULL, NULL, NULL FROM crm_appointment_history h INNER JOIN crm_appointment a ON a.tenant_id = h.tenant_id AND a.id = h.appointment_id INNER JOIN crm_customer c ON c.tenant_id = a.tenant_id AND c.id = a.customer_id AND c.deleted = 0 WHERE h.tenant_id = #{query.tenantId} AND h.from_status = 'CHECKED_IN' AND h.to_status = 'SERVICE_DONE' AND h.created_at >= #{query.window.fromUtc} AND h.created_at < #{query.window.toUtcExclusive}
AND a.customer_id = #{query.criteria.customerId} AND a.institution_id = #{query.criteria.institutionId} UNION ALL SELECT 'REDEMPTION', l.id, r.id, NULL, r.customer_id, NULL, NULL, NULL, r.posted_at, NULL, l.count, NULL, NULL FROM crm_redemption_line l INNER JOIN crm_redemption r ON r.tenant_id = l.tenant_id AND r.id = l.redemption_id AND r.status = 'POSTED' INNER JOIN crm_customer c ON c.tenant_id = r.tenant_id AND c.id = r.customer_id AND c.deleted = 0 WHERE l.tenant_id = #{query.tenantId} AND r.posted_at IS NOT NULL AND r.posted_at >= #{query.window.fromUtc} AND r.posted_at < #{query.window.toUtcExclusive}
AND r.customer_id = #{query.criteria.customerId} AND r.institution_id = #{query.criteria.institutionId} UNION ALL SELECT 'PAYMENT', p.id, o.id, o.id, o.customer_id, o.campaign_id, o.campaign_batch_id, NULL, p.confirmed_at, p.amount_fen, NULL, o.source_system, p.receiver_type FROM crm_payment_txn p INNER JOIN crm_order o ON o.tenant_id = p.tenant_id AND o.id = p.order_id AND o.status IN ('PAID','PARTIALLY_REDEEMED','FULFILLED') INNER JOIN crm_customer c ON c.tenant_id = o.tenant_id AND c.id = o.customer_id AND c.deleted = 0 WHERE p.tenant_id = #{query.tenantId} AND p.status = 'CONFIRMED' AND p.confirmed_at IS NOT NULL AND p.confirmed_at >= #{query.window.fromUtc} AND p.confirmed_at < #{query.window.toUtcExclusive}
UNION ALL SELECT 'REFUND', rp.id, r.id, o.id, r.customer_id, o.campaign_id, o.campaign_batch_id, NULL, rp.succeeded_at, rp.amount_fen, NULL, o.source_system, o.receiver_type FROM crm_refund_payment rp INNER JOIN crm_refund r ON r.tenant_id = rp.tenant_id AND r.id = rp.refund_id AND r.status = 'SUCCEEDED' INNER JOIN crm_order o ON o.tenant_id = r.tenant_id AND o.id = r.order_id AND o.status IN ('PAID','PARTIALLY_REDEEMED','FULFILLED') INNER JOIN crm_customer c ON c.tenant_id = r.tenant_id AND c.id = r.customer_id AND c.deleted = 0 WHERE rp.tenant_id = #{query.tenantId} AND rp.status = 'SUCCEEDED' AND rp.succeeded_at IS NOT NULL AND rp.succeeded_at >= #{query.window.fromUtc} AND rp.succeeded_at < #{query.window.toUtcExclusive}

mapper.select:
SELECT COUNT(*)
FROM crm_customer c
WHERE c.tenant_id = #{query.tenantId} AND c.deleted = 0
  AND c.created_at >= #{query.window.fromUtc} AND c.created_at < #{query.window.toUtcExclusive}

  AND c.id = #{query.criteria.customerId}

mapper.sql:
SELECT 'PAYMENT' AS fact_type, p.id AS source_id, o.id AS parent_id, o.id AS order_id, o.customer_id, o.campaign_id, o.campaign_batch_id, NULL AS sku_id, AS attribution_user_id, p.confirmed_at AS event_at, p.amount_fen, NULL AS quantity, o.source_system, p.receiver_type FROM crm_payment_txn p INNER JOIN crm_order o ON o.tenant_id = p.tenant_id AND o.id = p.order_id AND o.status IN ('PAID','PARTIALLY_REDEEMED','FULFILLED')
INNER JOIN crm_customer c ON c.tenant_id = o.tenant_id AND c.id = o.customer_id AND c.deleted = 0 WHERE p.tenant_id = #{query.tenantId} AND p.status = 'CONFIRMED' AND p.confirmed_at IS NOT NULL AND p.confirmed_at >= #{query.window.fromUtc} AND p.confirmed_at < #{query.window.toUtcExclusive}
UNION ALL SELECT 'REFUND', rp.id, r.id, o.id, r.customer_id, o.campaign_id, o.campaign_batch_id, NULL, , rp.succeeded_at, rp.amount_fen, NULL, o.source_system, o.receiver_type FROM crm_refund_payment rp INNER JOIN crm_refund r ON r.tenant_id = rp.tenant_id AND r.id = rp.refund_id AND r.status = 'SUCCEEDED' INNER JOIN crm_order o ON o.tenant_id = r.tenant_id AND o.id = r.order_id AND o.status IN ('PAID','PARTIALLY_REDEEMED','FULFILLED')
INNER JOIN crm_customer c ON c.tenant_id = r.tenant_id AND c.id = r.customer_id AND c.deleted = 0 WHERE rp.tenant_id = #{query.tenantId} AND rp.status = 'SUCCEEDED' AND rp.succeeded_at IS NOT NULL AND rp.succeeded_at >= #{query.window.fromUtc} AND rp.succeeded_at < #{query.window.toUtcExclusive}

mapper.select:
SELECT staff_user_id AS staffUserId, target_fen AS targetFen
FROM crm_performance_snapshot
WHERE tenant_id = #{query.tenantId} AND performance_role = #{performanceRole}
  AND period_key = #{periodKey} AND status = 'APPROVED' AND approved_by IS NOT NULL
  AND target_fen IS NOT NULL AND rule_version = #{query.criteria.metricVersion}


    AND staff_user_id IN #{staffId}

  AND 1 = 0

mapper.sql:
SELECT 'PAYMENT' AS fact_type, p.id AS source_id, o.id AS parent_id, o.id AS order_id, o.customer_id, o.campaign_id, o.campaign_batch_id, o.campaign_code_snapshot AS campaign_code, o.campaign_name_snapshot AS campaign_name, o.batch_code_snapshot AS batch_code, o.batch_name_snapshot AS batch_name, p.confirmed_at AS event_at, p.amount_fen, NULL AS quantity, o.source_system, p.receiver_type FROM crm_payment_txn p INNER JOIN crm_order o ON o.tenant_id = p.tenant_id AND o.id = p.order_id AND o.status IN ('PAID','PARTIALLY_REDEEMED','FULFILLED') INNER JOIN crm_customer c ON c.tenant_id = o.tenant_id AND c.id = o.customer_id AND c.deleted = 0 WHERE p.tenant_id = #{query.tenantId} AND p.status = 'CONFIRMED' AND p.confirmed_at IS NOT NULL AND p.confirmed_at >= #{query.window.fromUtc} AND p.confirmed_at < #{query.window.toUtcExclusive}
UNION ALL SELECT 'REFUND', rp.id, r.id, o.id, r.customer_id, o.campaign_id, o.campaign_batch_id, o.campaign_code_snapshot, o.campaign_name_snapshot, o.batch_code_snapshot, o.batch_name_snapshot, rp.succeeded_at, rp.amount_fen, NULL, o.source_system, o.receiver_type FROM crm_refund_payment rp INNER JOIN crm_refund r ON r.tenant_id = rp.tenant_id AND r.id = rp.refund_id AND r.status = 'SUCCEEDED' INNER JOIN crm_order o ON o.tenant_id = r.tenant_id AND o.id = r.order_id AND o.status IN ('PAID','PARTIALLY_REDEEMED','FULFILLED') INNER JOIN crm_customer c ON c.tenant_id = r.tenant_id AND c.id = r.customer_id AND c.deleted = 0 WHERE rp.tenant_id = #{query.tenantId} AND rp.status = 'SUCCEEDED' AND rp.succeeded_at IS NOT NULL AND rp.succeeded_at >= #{query.window.fromUtc} AND rp.succeeded_at < #{query.window.toUtcExclusive}
UNION ALL SELECT 'APPOINTMENT_CONFIRMED', h.id, a.id, o.id, a.customer_id, o.campaign_id, o.campaign_batch_id, o.campaign_code_snapshot, o.campaign_name_snapshot, o.batch_code_snapshot, o.batch_name_snapshot, h.created_at, NULL, NULL, o.source_system, o.receiver_type FROM crm_appointment_history h INNER JOIN crm_appointment a ON a.tenant_id = h.tenant_id AND a.id = h.appointment_id INNER JOIN crm_customer c ON c.tenant_id = a.tenant_id AND c.id = a.customer_id AND c.deleted = 0 INNER JOIN crm_appointment_item ai ON ai.tenant_id = a.tenant_id AND ai.appointment_id = a.id INNER JOIN crm_entitlement e ON e.tenant_id = ai.tenant_id AND e.id = ai.entitlement_id
WHERE h.tenant_id = #{query.tenantId} AND h.to_status = 'CONFIRMED' AND h.created_at >= #{query.window.fromUtc} AND h.created_at < #{query.window.toUtcExclusive}
AND a.institution_id = #{query.criteria.institutionId} UNION ALL SELECT 'CHECKED_IN', h.id, a.id, o.id, a.customer_id, o.campaign_id, o.campaign_batch_id, o.campaign_code_snapshot, o.campaign_name_snapshot, o.batch_code_snapshot, o.batch_name_snapshot, h.created_at, NULL, NULL, o.source_system, o.receiver_type FROM crm_appointment_history h INNER JOIN crm_appointment a ON a.tenant_id = h.tenant_id AND a.id = h.appointment_id INNER JOIN crm_customer c ON c.tenant_id = a.tenant_id AND c.id = a.customer_id AND c.deleted = 0 INNER JOIN crm_appointment_item ai ON ai.tenant_id = a.tenant_id AND ai.appointment_id = a.id INNER JOIN crm_entitlement e ON e.tenant_id = ai.tenant_id AND e.id = ai.entitlement_id
WHERE h.tenant_id = #{query.tenantId} AND h.to_status = 'CHECKED_IN' AND h.created_at >= #{query.window.fromUtc} AND h.created_at < #{query.window.toUtcExclusive}
AND a.institution_id = #{query.criteria.institutionId} UNION ALL SELECT 'REDEMPTION', l.id, r.id, o.id, r.customer_id, o.campaign_id, o.campaign_batch_id, o.campaign_code_snapshot, o.campaign_name_snapshot, o.batch_code_snapshot, o.batch_name_snapshot, r.posted_at, NULL, l.count, o.source_system, o.receiver_type FROM crm_redemption_line l INNER JOIN crm_redemption r ON r.tenant_id = l.tenant_id AND r.id = l.redemption_id AND r.status = 'POSTED' INNER JOIN crm_customer c ON c.tenant_id = r.tenant_id AND c.id = r.customer_id AND c.deleted = 0 INNER JOIN crm_entitlement e ON e.tenant_id = l.tenant_id AND e.id = l.entitlement_id
WHERE l.tenant_id = #{query.tenantId} AND r.posted_at IS NOT NULL AND r.posted_at >= #{query.window.fromUtc} AND r.posted_at < #{query.window.toUtcExclusive}
AND r.institution_id = #{query.criteria.institutionId}

mapper.select:
SELECT COUNT(*) FROM crm_sku s
WHERE s.tenant_id = #{query.tenantId}
  AND s.id = #{query.criteria.skuId}
